def summarize_sessions(events: list[dict], *, active_window: int) -> dict:
    sessions = {}
    for event in events:
        if 'session_id' not in event or 'timestamp' not in event:
            continue
        session_id = event['session_id']
        timestamp = event['timestamp']

        if session_id not in sessions:
            sessions[session_id] = {'history': [], 'active_window': 0}

        if len(sessions[session_id]['history']) >= active_window:
            sessions[session_id]['history'].pop(0)

        sessions[session_id]['history'].append(timestamp)

    return {k: v for k, v in sorted(sessions.items(), key=lambda item: item[1]['history'][-1])}
